const idType = "studentId";
const student = {
  [idType]: "A123456",
  sName: "Vinod",
  sAge: 29,
  greet() {
    console.log(`Hey, my ${idType} is ${this[idType]} and my name is ${this.sName}.`);
  },
};
student.greet();
student.job = "web dev";
student["sAge"] = 30;
delete student.greet;
console.log(student);
console.log("job" in student, Object.hasOwn(student, "toString"), "toString" in student);
console.log(student.missing, student.missing?.deep);

const product = { id: 1, name: "Laptop", price: 999.99, stock: 50 };
console.log(Object.keys(product));
console.log(Object.values(product));
console.log(Object.entries(product));

for (const [key, value] of Object.entries(product)) console.log(`${key} -> ${value}`);

const discounted = Object.fromEntries(
  Object.entries(product).map(([k, v]) => [k, typeof v === "number" ? v * 0.9 : v])
);
console.log(discounted);

const target = { a: 1, b: 2 }, source = { b: 3, c: 4 };
console.log(Object.assign({}, target, source), { ...target, ...source });

const dict = Object.create(null);
dict.name = "vinod";
console.log(Object.hasOwn(dict, "name"));

let a = 10, b = a; b = 20;
console.log(a, b);

const original = { id: 5, name: "kody", tags: ["js"], meta: { views: 1 } };
const ref = original;
const shallow = { ...original };
const deep = structuredClone(original);

ref.name = "changed";
shallow.meta.views = 99;
deep.tags.push("deep-only");

console.log(original.name, original.meta.views, original.tags);
console.log(deep.tags, shallow === original, ref === original);

function change(o) { o.x = 1; o = { replaced: true }; }
const target = {};
change(target);
console.log(target);

(function () {
"use strict";
const config = Object.freeze({ api: "/v1", nested: { retries: 3 } });
try { config.api = "/v2"; } catch (e) { console.log("freeze:", e.constructor.name); }
config.nested.retries = 5;           // shallow - still allowed
console.log(config.nested.retries, Object.isFrozen(config));

const sealed = Object.seal({ a: 1 });
sealed.a = 2;
try { delete sealed.a; } catch (e) { console.log("seal:", e.constructor.name); }
console.log(sealed);

const user = {};
Object.defineProperty(user, "id", { value: 7, enumerable: false });
Object.defineProperty(user, "name", { value: "Asha", enumerable: true });
console.log(Object.keys(user), user.id);
console.log(Object.getOwnPropertyDescriptor(user, "id"));
})();

const data = { name: "Vinod", age: 30, city: "pune", skip: undefined, fn() {}, joined: new Date(0) };
const json = JSON.stringify(data);
console.log(json);
console.log(JSON.stringify([undefined, function () {}, NaN]));
console.log(JSON.stringify({ a: 1, b: [1, 2] }, null, 2));

const parsed = JSON.parse('{"name":"Vinod","age":30,"city":"pune"}');
console.log(parsed.name, typeof parsed);

try {
  JSON.parse("{'bad': 'json'}");
} catch (e) {
  console.log(e.name);
}
console.log(JSON.parse('{"d":"2024-01-01"}', (k, v) => (k === "d" ? new Date(v).getUTCFullYear() : v)));

const words = "to be or not to be".split(" ");
const counts = new Map();
for (const w of words) counts.set(w, (counts.get(w) ?? 0) + 1);
console.log(counts, counts.size);
console.log([...counts].sort((a, b) => b[1] - a[1])[0]);

const unique = new Set([1, 2, 2, 3, NaN, NaN]);
console.log(unique, unique.has(NaN), unique.size);

const objKey = { id: 1 };
const registry = new Map([[objKey, "first"]]);
console.log(registry.get(objKey), registry.get({ id: 1 }));
console.log(Object.fromEntries(counts));

const id = Symbol("id");
const user = { name: "Asha", [id]: 42 };
console.log(Object.keys(user), user[id], id.description);
console.log(Symbol("a") === Symbol("a"), Symbol.for("a") === Symbol.for("a"));

const secrets = new WeakMap();
let obj = { label: "temp" };
secrets.set(obj, "hidden value");
console.log(secrets.get(obj), secrets.has({}));

